    priority_patterns = [
        (6, [r'GRAND\s+TOTAL']),
        (5, [r'TOTAL\s*:?\s*RM\b']),
        (4, [r'TOTAL\s+(AMOUNT|AMT)\b']),
        (3, [r'TOTAL\s+DUE', r'(AMOUNT|AMT)\s+DUE', r'BALANCE\s+DUE',
             r'\bNETT?\s+TOTAL\b']),
        (2, [r'\bTOTAL\b']),
        (1, [r'\bAMOUNT\b']),
