    exclusion_patterns = [
        r'SUB\s*-?\s*TOTAL',
        r'SUBTOTAL',
        r'TOTAL\s*GST', r'TOTAL\s*TAX', r'TOTAL\s*SST',
        r'TOTAL\s+ITEM', r'TOTAL\s+QTY', r'TOTAL\s+SAVINGS',
        r'\bDISCOUNT\b',
        r'\bCHANGE\b',
        r'CASH\s*TENDERED',
        r'\bEXCL\w*\b',
        r'\bROUNDING\b',
        r'^\s*(GST|TAX|SST)\b',
        r'\b(GST|TAX|SST)\s+AMT\b',
        r'\b(GST|TAX|SST)\s+AMOUNT\b',
        r'AMOUNT\s*\(RM\)',
    ]

    def is_excluded(up):
        return any(re.search(p, up) for p in exclusion_patterns)

    def get_numbers(s):
        return re.findall(
            r'(?<![\d\.])\d{1,3}(?:,\d{3})+\.\d{2}|(?<![\d\.])\d+\.\d{2}', s)

