import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

MONTHS = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
          'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}


def normalize_numbers(text):
    # '49. 40' -> '49.40'
    text = re.sub(r'(\d)\.\s+(\d{2})(?!\d)', r'\1.\2', text)
    # '48,95' or '48, 95' -> '48.95' (but keep thousands like '1,234')
    text = re.sub(r'(?<!\d)(\d+),\s*(\d{2})(?!\d)', r'\1.\2', text)
    return text


def parse_date_components(d, m, y):
    try:
        d, m, y = int(d), int(m), int(y)
    except ValueError:
        return None
    if y < 100:
        y += 2000 if y < 70 else 1900
    if 1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
        return f"{y:04d}-{m:02d}-{d:02d}"
    return None


def extract_date(text):
    date_regex_num = re.compile(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})\b')
    date_regex_mon = re.compile(
        r'\b(\d{1,2})\s+([A-Za-z]{3,})\s+(\d{2,4})\b', re.IGNORECASE)

    lines = text.split('\n')
    for line in lines:
        if re.search(r'\bDate\b', line, re.IGNORECASE):
            for m in date_regex_num.finditer(line):
                r = parse_date_components(*m.groups())
                if r:
                    return r
            for m in date_regex_mon.finditer(line):
                mon = MONTHS.get(m.group(2)[:3].lower())
                if mon:
                    r = parse_date_components(m.group(1), mon, m.group(3))
                    if r:
                        return r

    for m in date_regex_num.finditer(text):
        r = parse_date_components(*m.groups())
        if r:
            return r
    for m in date_regex_mon.finditer(text):
        mon = MONTHS.get(m.group(2)[:3].lower())
        if mon:
            r = parse_date_components(m.group(1), mon, m.group(3))
            if r:
                return r
    return None


def extract_total(text):
    priority_patterns = [
        (6, [r'GRAND\s+TOTAL']),
        (5, [r'TOTAL\s*:?\s*RM\b']),
        (4, [r'TOTAL\s+(AMOUNT|AMT)\b']),
        (3, [r'TOTAL\s+DUE', r'(AMOUNT|AMT)\s+DUE', r'BALANCE\s+DUE',
             r'\bNETT?\s+TOTAL\b']),
        (2, [r'\bTOTAL\b']),
        (1, [r'\bAMOUNT\b']),
    ]

    exclusion_patterns = [
        r'SUB\s*-?\s*TOTAL',
        r'SUBTOTAL',
        r'TOTAL\s*GST', r'TOTAL\s*TAX', r'TOTAL\s*SST',
        r'TOTAL\s+ITEM', r'TOTAL\s+QTY', r'TOTAL\s+SAVINGS',
        r'\bDISCOUNT\b',
        r'\bCHANGE\b',
        r'CASH\s*TENDERED',
        r'\bEXCL\w*\b',
        r'\bROUNDING\b',
        r'^\s*(GST|TAX|SST)\b',
        r'\b(GST|TAX|SST)\s+AMT\b',
        r'\b(GST|TAX|SST)\s+AMOUNT\b',
        r'AMOUNT\s*\(RM\)',
    ]

    def is_excluded(up):
        return any(re.search(p, up) for p in exclusion_patterns)

    def get_numbers(s):
        return re.findall(
            r'(?<![\d\.])\d{1,3}(?:,\d{3})+\.\d{2}|(?<![\d\.])\d+\.\d{2}', s)

    lines = text.split('\n')
    cut = len(lines)
    for i, line in enumerate(lines):
        if re.search(r'SUMMARY', line.upper()):
            cut = i
            break
    lines = lines[:cut]

    for priority, patterns in priority_patterns:
        matches = []
        for i, line in enumerate(lines):
            up = line.upper()
            if is_excluded(up):
