            if is_excluded(up):
                continue
            if any(re.search(p, up) for p in patterns):
                nums = get_numbers(line)
                if not nums and i + 1 < len(lines):
                    nums = get_numbers(lines[i + 1])
                if nums:
                    matches.append(nums[-1].replace(',', ''))
        if matches:
            return matches[-1]
    return None


def process_receipts(img_dir, output_xlsx):
    rows = []
    for fn in sorted(os.listdir(img_dir)):
        path = os.path.join(img_dir, fn)
        img = Image.open(path)
        text = pytesseract.image_to_string(img, config='--psm 6')
        text = normalize_numbers(text)
        date = extract_date(text)
        total = extract_total(text)
        rows.append((fn, date, total))
        print(f"{fn}: date={date}, total={total}")

    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fn, d, t in rows:
