                if not nums and priority >= 2 and i + 1 < len(lines):
                    nums = get_numbers(lines[i + 1])
                    used_fallback = True
                if nums:
                    matches.append((used_fallback, nums[-1].replace(',', '')))
        if matches:
            used_fallback, value = matches[-1]
            return (priority, used_fallback, value)
    return None"}
